// Process Drive files into assets
const yachtData = $('Get Yacht Data').first().json;
const files = $input.all().map(i => i.json);

const videoTypes = ['video/mp4', 'video/quicktime', 'video/x-msvideo', 'video/webm'];
const imageTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/heic'];

const assets = files.map(file => {
  const isVideo = videoTypes.some(t => file.mimeType?.includes(t) || file.mimeType?.startsWith('video/'));
  const isImage = imageTypes.some(t => file.mimeType?.includes(t) || file.mimeType?.startsWith('image/'));

  if (!isVideo && !isImage) return null;

  // Auto-tag based on filename
  const name = (file.name || '').toLowerCase();
  let autoTag = 'untagged';

  if (name.includes('drone') || name.includes('aerial') || name.includes('dji')) autoTag = 'drone';
  else if (name.includes('interior') || name.includes('cabin') || name.includes('salon')) autoTag = 'interior';
  else if (name.includes('exterior') || name.includes('deck')) autoTag = 'exterior';
  else if (name.includes('sunset') || name.includes('ocean') || name.includes('sea')) autoTag = 'ocean';
  else if (name.includes('jacuzzi') || name.includes('jet') || name.includes('toy')) autoTag = 'toys';
  else if (name.includes('crew') || name.includes('service') || name.includes('chef')) autoTag = 'crew';
  else if (name.includes('lifestyle') || name.includes('party') || name.includes('guest')) autoTag = 'lifestyle';

  return {
    asset_id: file.id,
    yacht_id: yachtData.yacht_id,
    type: isVideo ? 'video' : 'photo',
    filename: file.name,
    tag: autoTag,
    mime_type: file.mimeType,
    size_bytes: parseInt(file.size) || 0,
    url: file.webContentLink || `https://drive.google.com/file/d/${file.id}/view`,
    thumbnail_url: file.thumbnailLink || null,
    modified_at: file.modifiedTime,
    indexed_at: new Date().toISOString()
  };
}).filter(Boolean);

return assets.map(a => ({ json: a }));

// Summarize indexed assets
const assets = $('Process Files to Assets').all().map(i => i.json);

const summary = {
  total: assets.length,
  videos: assets.filter(a => a.type === 'video').length,
  photos: assets.filter(a => a.type === 'photo').length,
  byTag: {}
};

assets.forEach(a => {
  summary.byTag[a.tag] = (summary.byTag[a.tag] || 0) + 1;
});

return [{ json: summary }];
